import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored. Column names follow SQL conventions; `toJob` maps them to the API shape. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed_steps: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  claimed_by: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;');
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      completed_steps INTEGER NOT NULL DEFAULT 0,
      result_output TEXT,
      error TEXT,
      idempotency_key TEXT UNIQUE,
      claimed_by TEXT,
      available_at INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
    CREATE TABLE IF NOT EXISTS workers (
      worker_id TEXT PRIMARY KEY,
      heartbeat_ms INTEGER NOT NULL
    );
  `);
  return db;
}

/** Runs `fn` inside a write transaction that takes the database write lock up front. */
export function immediateTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { immediateTransaction, openDatabase, type JobRow, type JobStatus } from './db.ts';

const WORKER_STALE_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;
const MAX_INPUT_LENGTH = 1000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

interface FieldError {
  field: string;
  message: string;
}

class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
    readonly fields?: FieldError[],
  ) {
    super(message);
  }
}

/** Public job shape returned by every endpoint that returns a job. */
interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed_steps, total: r.steps },
    result: r.status === 'completed' && r.result_output !== null ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, err: ApiError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  send(res, err.status, { error });
}

function invalid(fields: FieldError[]): ApiError {
  return new ApiError(400, 'invalid_request', 'The request is invalid.', fields);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (!header) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

function parseIntegerField(obj: Record<string, unknown>, name: string, min: number, max: number, def: number, errors: FieldError[]): number {
  if (!(name in obj) || obj[name] === undefined) return def;
  const v = obj[name];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return def;
  }
  return v;
}

/** Validates the parsed JSON body. Returns the payload with defaults applied. */
function validatePayload(body: unknown): NewJob {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    throw invalid([{ field: 'body', message: 'must be a JSON object' }]);
  }
  const obj = body as Record<string, unknown>;
  const errors: FieldError[] = [];
  for (const key of Object.keys(obj)) {
    if (key !== 'input' && key !== 'steps' && key !== 'failAttempts') {
      errors.push({ field: key, message: 'is not a recognised field' });
    }
  }
  let input = '';
  if (!('input' in obj)) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof obj.input !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (obj.input.trim() === '') {
    errors.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = obj.input;
  }
  const steps = parseIntegerField(obj, 'steps', 1, 20, DEFAULT_STEPS, errors);
  const failAttempts = parseIntegerField(obj, 'failAttempts', 0, 5, DEFAULT_FAIL_ATTEMPTS, errors);
  if (errors.length > 0) throw invalid(errors);
  return { input, steps, failAttempts };
}

const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

async function createJob(req: IncomingMessage): Promise<{ status: number; job: Job }> {
  const keyHeader = req.headers['idempotency-key'];
  const key = keyHeader === undefined ? undefined : String(keyHeader);
  const keyErrors: FieldError[] = [];
  if (key !== undefined && !IDEMPOTENCY_KEY.test(key)) {
    keyErrors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    await readBody(req);
    throw invalid([...keyErrors, { field: 'body', message: 'Content-Type must be application/json' }]);
  }
  const { text, tooLarge } = await readBody(req);
  if (tooLarge) throw invalid([...keyErrors, { field: 'body', message: 'body is too large' }]);
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw invalid([...keyErrors, { field: 'body', message: 'is not valid JSON' }]);
  }
  let payload: NewJob;
  try {
    payload = validatePayload(parsed);
  } catch (e) {
    if (e instanceof ApiError && keyErrors.length > 0) throw invalid([...keyErrors, ...(e.fields ?? [])]);
    throw e;
  }
  if (keyErrors.length > 0) throw invalid(keyErrors);

  return immediateTransaction(db, () => {
    if (key !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as JobRow | undefined;
      if (existing) {
        const same = existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
        if (!same) {
          throw new ApiError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
        }
        return { status: 200, job: toJob(existing) };
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed_steps, idempotency_key, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, key ?? null, now, now);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    return { status: 201, job: toJob(row) };
  });
}

function workerIsUp(): boolean {
  const row = db.prepare('SELECT 1 AS ok FROM workers WHERE heartbeat_ms >= ? LIMIT 1').get(Date.now() - WORKER_STALE_MS);
  return row !== undefined;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') throw new ApiError(405, 'method_not_allowed', 'Method not allowed.');
    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') throw new ApiError(405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') {
      const { status, job } = await createJob(req);
      return send(res, status, job);
    }
    throw new ApiError(405, 'method_not_allowed', 'Method not allowed.');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') throw new ApiError(405, 'method_not_allowed', 'Method not allowed.');
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(match[1]!) as JobRow | undefined;
    if (!row) throw new ApiError(404, 'not_found', 'No job with that id.');
    return send(res, 200, toJob(row));
  }

  throw new ApiError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    if (res.headersSent) {
      res.end();
      return;
    }
    if (e instanceof ApiError) {
      sendError(res, e);
      return;
    }
    console.error('unhandled error', e);
    sendError(res, new ApiError(500, 'internal_error', 'Internal error.'));
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import { randomUUID } from 'node:crypto';
import { setTimeout as sleep } from 'node:timers/promises';
import { immediateTransaction, openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 500;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
/** A worker whose heartbeat is older than this is considered dead; its running jobs are requeued. */
const WORKER_DEAD_MS = 5_000;

const workerId = randomUUID();
const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function nowIso(): string {
  return new Date().toISOString();
}

function heartbeat(): void {
  db.prepare(
    `INSERT INTO workers (worker_id, heartbeat_ms) VALUES (?, ?)
     ON CONFLICT (worker_id) DO UPDATE SET heartbeat_ms = excluded.heartbeat_ms`,
  ).run(workerId, Date.now());
}

/**
 * Requeues jobs claimed by workers that have stopped heartbeating (for example after SIGKILL).
 * The interrupted attempt is rolled back, so the job is retried as the same attempt number.
 */
function recoverAbandonedJobs(): void {
  db.prepare(
    `UPDATE jobs
        SET status = 'queued', attempts = MAX(attempts - 1, 0), completed_steps = 0, claimed_by = NULL, updated_at = ?
      WHERE status = 'running'
        AND claimed_by IS NOT NULL
        AND claimed_by != ?
        AND claimed_by NOT IN (SELECT worker_id FROM workers WHERE heartbeat_ms >= ?)`,
  ).run(nowIso(), workerId, Date.now() - WORKER_DEAD_MS);
}

/** Claims the oldest runnable queued job. Returns undefined when there is none. */
function claimNext(): JobRow | undefined {
  return immediateTransaction(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1`)
      .get(Date.now()) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0, claimed_by = ?, updated_at = ?
        WHERE id = ? AND status = 'queued'`,
    ).run(workerId, nowIso(), next.id);
    return db.prepare('SELECT * FROM jobs WHERE id = ?').get(next.id) as unknown as JobRow;
  });
}

/** Puts an interrupted attempt back in the queue without counting it. */
function rollBack(id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed_steps = 0, claimed_by = NULL, updated_at = ?
      WHERE id = ? AND claimed_by = ?`,
  ).run(nowIso(), id, workerId);
}

function finishAttempt(job: JobRow): void {
  const attempt = job.attempts;
  if (attempt <= job.fail_attempts) {
    // Transient failure at the first step, before any progress.
    if (attempt < MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'queued', available_at = ?, claimed_by = NULL, updated_at = ? WHERE id = ?`,
      ).run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    } else {
      db.prepare(
        `UPDATE jobs SET status = 'failed', error = 'transient failure', claimed_by = NULL, updated_at = ? WHERE id = ?`,
      ).run(nowIso(), job.id);
    }
    return;
  }
  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, completed_steps = steps, claimed_by = NULL, updated_at = ? WHERE id = ?`,
  ).run(job.input.toUpperCase(), nowIso(), job.id);
}

/** Runs one claimed attempt step by step, then records its outcome. Rolls back if asked to stop mid-attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  const steps = job.steps;
  const failing = job.attempts <= job.fail_attempts;
  // The first step always takes its time; a failing attempt fails at the end of that step.
  for (let i = 1; i <= steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      rollBack(job.id);
      return;
    }
    if (failing) break;
    db.prepare('UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND claimed_by = ?').run(i, nowIso(), job.id, workerId);
  }
  finishAttempt(job);
}

heartbeat();
const heartbeatTimer = setInterval(() => {
  try {
    heartbeat();
  } catch (e) {
    console.error('heartbeat failed', e);
  }
}, HEARTBEAT_MS);

console.log(`worker started (${workerId})`);
recoverAbandonedJobs();
while (!stopping) {
  try {
    heartbeat();
    recoverAbandonedJobs();
    const job = claimNext();
    if (job) {
      await runAttempt(job);
    } else {
      await sleep(POLL_MS);
    }
  } catch (e) {
    console.error('worker error', e);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeatTimer);
db.prepare('DELETE FROM workers WHERE worker_id = ?').run(workerId);
db.close();
console.log('worker stopped');
