<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Job tracker</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; color: #222; }
    form { display: grid; grid-template-columns: 1fr 7rem 9rem; gap: .5rem; align-items: end; margin-bottom: 1rem; }
    label { display: flex; flex-direction: column; font-size: .85rem; gap: .25rem; }
    input { font: inherit; padding: .4rem; }
    button { font: inherit; padding: .4rem 1rem; grid-column: 1 / -1; justify-self: start; }
    [data-testid="form-error"] { color: #b00020; min-height: 1.2rem; margin-bottom: 1rem; white-space: pre-line; }
    ul { list-style: none; padding: 0; margin: 0; }
    li { border: 1px solid #ddd; border-radius: 6px; padding: .6rem .8rem; margin-bottom: .5rem; display: grid; grid-template-columns: 6rem 5rem 1fr; gap: .5rem; align-items: baseline; }
    .input { grid-column: 1 / -1; color: #666; font-size: .85rem; word-break: break-all; }
    .result { word-break: break-all; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>

  <div data-testid="form-error" role="alert" id="form-error"></div>

  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    const form = document.getElementById('job-form');
    const errorBox = document.getElementById('form-error');
    const list = document.getElementById('job-list');
    const submitButton = form.querySelector('[data-testid="job-submit"]');

    // Numeric text becomes a number so the API validates it; anything else is sent as typed.
    function fieldValue(raw) {
      const text = raw.trim();
      if (text === '') return undefined;
      return /^[-+]?\d+(\.\d+)?$/.test(text) ? Number(text) : raw;
    }

    function describeError(body, status) {
      const error = body && body.error;
      if (!error) return 'Request failed with status ' + status + '.';
      let text = error.message || 'Request failed.';
      if (Array.isArray(error.fields) && error.fields.length > 0) {
        text += '\n' + error.fields.map((f) => f.field + ': ' + f.message).join('\n');
      }
      return text;
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorBox.textContent = '';
      const data = new FormData(form);
      const body = {};
      const input = data.get('input');
      body.input = input === null ? '' : input;
      const steps = fieldValue(data.get('steps') ?? '');
      const failAttempts = fieldValue(data.get('failAttempts') ?? '');
      if (steps !== undefined) body.steps = steps;
      if (failAttempts !== undefined) body.failAttempts = failAttempts;

      submitButton.disabled = true;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        const json = await res.json().catch(() => null);
        if (!res.ok) {
          errorBox.textContent = describeError(json, res.status);
          return;
        }
        form.querySelector('[data-testid="job-input"]').value = '';
        await refresh();
      } catch (e) {
        errorBox.textContent = 'Could not reach the server: ' + e.message;
      } finally {
        submitButton.disabled = false;
      }
    });

    const items = new Map();

    function renderJob(li, job) {
      li.querySelector('[data-testid="job-status"]').textContent = job.status;
      li.querySelector('[data-testid="job-progress"]').textContent = job.progress.completed + '/' + job.progress.total;
      let resultText = '';
      if (job.status === 'completed' && job.result) resultText = job.result.output;
      else if (job.status === 'failed') resultText = job.error || '';
      li.querySelector('[data-testid="job-result"]').textContent = resultText;
      li.querySelector('.input').textContent = JSON.stringify(job.input);
    }

    function createItem(job) {
      const li = document.createElement('li');
      li.setAttribute('data-testid', 'job-item');
      li.setAttribute('data-job-id', job.id);
      const status = document.createElement('span');
      status.setAttribute('data-testid', 'job-status');
      const progress = document.createElement('span');
      progress.setAttribute('data-testid', 'job-progress');
      const result = document.createElement('span');
      result.setAttribute('data-testid', 'job-result');
      result.className = 'result';
      const input = document.createElement('span');
      input.className = 'input';
      li.append(status, progress, result, input);
      return li;
    }

    async function refresh() {
      const res = await fetch('/api/jobs');
      if (!res.ok) return;
      const { jobs } = await res.json();
      const seen = new Set();
      jobs.forEach((job) => {
        seen.add(job.id);
        let li = items.get(job.id);
        if (!li) {
          li = createItem(job);
          items.set(job.id, li);
        }
        renderJob(li, job);
        list.appendChild(li); // moves existing items too, so the order matches the API (newest first)
      });
      for (const [id, li] of items) {
        if (!seen.has(id)) {
          li.remove();
          items.delete(id);
        }
      }
    }

    refresh().catch(() => {});
    setInterval(() => refresh().catch(() => {}), 1000);
  </script>
</body>
</html>

